{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About · {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#fbfcfb;
      --card:#ffffff;
      --muted:#6b7280;
      --accent:#1f7a6b;
      --glass:rgba(255,255,255,0.7);
      --shadow:0 6px 24px rgba(16,24,40,0.06);
      --max-width:1000px;
      font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;
    }
    html,body{height:100%;margin:0;background:var(--bg);color:#052f2b}
    body{line-height:1.4}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px;max-width:var(--max-width);margin:0 auto}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;border-radius:10px;background:linear-gradient(180deg,var(--accent),#12685a);display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-size:14px}
    main{max-width:var(--max-width);margin:24px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr;gap:18px;padding:28px;border-radius:12px;background:linear-gradient(180deg,rgba(31,122,107,0.06),transparent);box-shadow:var(--shadow)}
    .hero h1{margin:0;font-size:26px;color:#053b36}
    .hero p{margin:0;color:var(--muted)}
    .cta{display:inline-block;margin-top:12px;padding:10px 16px;background:var(--accent);color:#fff;border-radius:8px;text-decoration:none}
    .card{background:var(--card);padding:18px;margin-top:18px;border-radius:10px;box-shadow:var(--shadow)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;align-items:start}
    .mission h2{margin-top:0}
    .pill{display:inline-block;background:var(--glass);padding:6px 10px;border-radius:999px;color:var(--accent);font-weight:600;font-size:13px}
    ul.habits{padding-left:18px;color:var(--muted)}
    footer{max-width:var(--max-width);margin:36px auto 60px;padding:0 20px;color:var(--muted);font-size:14px}

    /* reveal */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity 420ms ease,var(--transform,transform) 420ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .reveal{transition:none;opacity:1;transform:none}
    }

    /* planner */
    .planner-form label{display:block;margin-top:10px;font-weight:600;color:#053b36}
    .planner-form input[type="text"],.planner-form select,.planner-form textarea{width:100%;padding:8px;border-radius:8px;border:1px solid #e6eef0;margin-top:6px}
    .planner-actions{display:flex;gap:8px;margin-top:12px}
    .btn{padding:9px 12px;border-radius:8px;border:0;background:#0f6f59;color:#fff;cursor:pointer}
    .btn.secondary{background:#eef7f5;color:var(--accent);border:1px solid #d7efe9}
    .summary{white-space:pre-wrap;background:#f7fffb;padding:12px;border-radius:8px;border:1px dashed #d6efe6;margin-top:12px;min-height:80px}

    /* small screens */
    @media (max-width:820px){.grid{grid-template-columns:1fr}.hero{padding:18px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">Who I Am</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Membership</a>
      <a href="book.html">Book</a>
      <a href="testimonials.html">Stories</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" data-delay="0">
      <span class="pill">Membership-based guidance</span>
      <h1>Practical rhythms that steady your days</h1>
      <p>Small, repeatable choices that align energy and priorities. We map habits into a weekly rhythm you can actually keep—one decision at a time.</p>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
    </section>

    <div class="grid" style="margin-top:18px">
      <div>
        <section class="card mission reveal" data-delay="120">
          <h2>A short note on how I work</h2>
          <p style="color:var(--muted)">I combine simple habit scaffolds, easy-to-follow frameworks, and measurable outcomes. No medical claims—just practical steps to change patterns and sharpen daily focus.</p>
          <h3 style="margin-bottom:6px">What we track</h3>
          <ul class="habits">
            <li>One intentional start to the day</li>
            <li>Two anchor habits for energy and calm</li>
            <li>Weekly reflections that inform your next week</li>
          </ul>
        </section>

        <section class="card micro_habits reveal" data-delay="240">
          <h2>Micro practices</h2>
          <p style="color:var(--muted)">Tiny, repeatable tasks designed to protect time and attention without overwhelming your schedule.</p>
          <ul class="habits">
            <li>3-minute breathing when transitions feel sharp</li>
            <li>One 10-minute check-in at midday</li>
            <li>A single nightly note of one win</li>
          </ul>
        </section>
      </div>

      <aside>
        <div class="card reveal" data-delay="360">
          <h3 style="margin-top:0">Quick diagnostic</h3>
          <p style="color:var(--muted)">Answer three prompts in your head: What takes energy? What protects it? What could be smaller? These answers form the outline of your first plan.</p>
          <div style="margin-top:10px"><strong>Need help?</strong> Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">Email</a></div>
        </div>

        <div class="card reveal" data-delay="480">
          <h3 style="margin-top:0">Session Planner</h3>
          <form class="planner-form" id="plannerAbout">
            <label for="name">Name</label>
            <input id="name" type="text" placeholder="Your name">
            <label for="goal">Primary goal for this month</label>
            <input id="goal" type="text" placeholder="Example: more stable energy through afternoons">
            <label for="time">Typical session length</label>
            <select id="time">
              <option>15 minutes</option>
              <option>30 minutes</option>
              <option>45 minutes</option>
            </select>
            <label>Focus areas</label>
            <div style="display:flex;gap:8px;margin-top:6px">
              <label><input type="checkbox" value="Sleep" class="focus"> Sleep</label>
              <label><input type="checkbox" value="Movement" class="focus"> Movement</label>
              <label><input type="checkbox" value="Nutrition" class="focus"> Nutrition</label>
            </div>
            <div class="planner-actions">
              <button type="button" class="btn" id="buildAbout">Build Plan</button>
              <button type="button" class="btn secondary" id="downloadAbout">Download</button>
            </div>
          </form>
          <div id="summaryAbout" class="summary" aria-live="polite">Your plan will appear here.</div>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="btn" id="copyAbout">Copy</button>
            <a class="btn secondary" href="{{PRIMARY_CTA_URL}}">Start membership</a>
          </div>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div>Contact: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    <div style="margin-top:8px;color:var(--muted)">Built for members in {{CITY}}, {{STATE}}—simple frameworks, steady progress.</div>
  </footer>

  <script>
    // Scroll reveal with prefers-reduced-motion support
    (function(){
      const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = document.querySelectorAll('.reveal');
      if(reduce){ reveals.forEach(r => r.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting){
            const el = entry.target; const d = el.getAttribute('data-delay') || 0;
            setTimeout(()=>el.classList.add('visible'), Number(d));
            io.unobserve(el);
          }
        });
      },{threshold:0.12});
      reveals.forEach(r=>io.observe(r));
    })();

    // Session Planner logic
    (function(){
      function gather(formRootId){
        const root = document.getElementById(formRootId);
        const name = root.querySelector('#name')?.value || '';
        const goal = root.querySelector('#goal')?.value || '';
        const time = root.querySelector('#time')?.value || '';
        const focusNodes = root.querySelectorAll('.focus');
        const focuses = Array.from(focusNodes).filter(n=>n.checked).map(n=>n.value);
        return {name,goal,time,focuses};
      }
      function makeText(data){
        const lines = [];
        lines.push('Session Planner — ' + new Date().toLocaleDateString());
        if(data.name) lines.push('Name: ' + data.name);
        if(data.goal) lines.push('Primary monthly goal: ' + data.goal);
        lines.push('Session length: ' + (data.time || '—'));
        lines.push('Focus areas: ' + (data.focuses.length ? data.focuses.join(', ') : 'General'));
        lines.push('Suggested weekly rhythm:');
        lines.push('  • 2 focused sessions at the chosen length (early week)');
        lines.push('  • 1 review + lightweight adjustment (end of week)');
        lines.push('Micro-commitments: pick one 3–10 minute task tied to a routine transition.');
        lines.push('\nNotes: Use this summary as a baseline. Adjust small steps each week to preserve momentum.');
        return lines.join('\n');
      }

      function wire(formId, summaryId, copyId, buildId, downloadId){
        const buildBtn = document.getElementById(buildId);
        const copyBtn = document.getElementById(copyId);
        const downloadBtn = document.getElementById(downloadId);
        const summaryEl = document.getElementById(summaryId);
        buildBtn.addEventListener('click', ()=>{
          const data = gather(formId.replace('', ''));
          const text = makeText(data);
          summaryEl.textContent = text;
        });
        copyBtn.addEventListener('click', async ()=>{
          try{
            await navigator.clipboard.writeText(summaryEl.textContent || '');
            copyBtn.textContent = 'Copied';
            setTimeout(()=>copyBtn.textContent = 'Copy',1200);
          }catch(e){
            console.error(e);
            copyBtn.textContent = 'Unable to copy';
          }
        });
        downloadBtn.addEventListener('click', ()=>{
          const blob = new Blob([summaryEl.textContent || ''],{type:'text/plain'});
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); a.remove();
          URL.revokeObjectURL(url);
        });
      }

      // wire the one on this page
      wire('plannerAbout','summaryAbout','copyAbout','buildAbout','downloadAbout');
    })();
  </script>
</body>
</html>"} 
