  <script>
    // Reveal behavior
    (function(){
      const prefersReduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){
            const el = e.target; const d = el.getAttribute('data-delay')||0;
            setTimeout(()=>el.classList.add('visible'), Number(d)); obs.unobserve(el);
          }
        });
      },{threshold:0.14});
      items.forEach(i=>obs.observe(i));
    })();

    // Compact planner
    (function(){
      function compose(){
        const name = document.getElementById('sname').value || '';
        const freq = document.getElementById('sfreq').value;
        const lines = [];
        lines.push('Membership plan sketch — ' + new Date().toLocaleDateString());
